const ADMIN_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Code inventory \u00b7 Palawan Collective Admin</title><style>\n:root{--bg:#f4f6f2;--ink:#213027;--muted:#717d73;--line:#dce3da;--green:#304d38}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:14px system-ui,sans-serif}button,input,select,textarea{font:inherit}button,a{cursor:pointer}a{color:var(--green);text-decoration:none}button:focus-visible,a:focus-visible{outline:3px solid #8aab67;outline-offset:3px}button{border:1px solid #cfd9cc;border-radius:6px;background:white;padding:9px 13px;color:var(--ink)}button:disabled{opacity:.5;cursor:wait}.primary{background:var(--green);color:white;border-color:var(--green)}.shell{display:grid;grid-template-columns:225px 1fr;min-height:100vh}aside{background:#20382b;color:#e6ece3;padding:32px 22px;position:sticky;top:0;height:100vh}.brand{font-size:20px;font-weight:750;letter-spacing:-.8px;line-height:1.05}.adminlabel{font-size:10px;letter-spacing:2px;opacity:.55;margin:14px 0 35px}aside nav button{display:block;width:100%;text-align:left;background:transparent;border:0;color:#c6d6c4;margin:6px 0;padding:13px}.active{background:#ffffff17!important;color:white!important}aside a{color:#cad9c6;font-size:12px;display:block;padding:15px 10px}.sidefoot{position:absolute;bottom:30px;font-size:11px;color:#9bb39e;line-height:1.7;max-width:175px}main{min-width:0;padding:35px 36px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:1.7px;color:var(--muted)}h1{font-size:31px;letter-spacing:-1.2px;margin:8px 0}.subtitle{font-size:13px;color:var(--muted);line-height:1.65;margin:10px 0 22px}.actions{display:flex;gap:8px;flex-wrap:wrap}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:25px 0}.stat{background:white;border:1px solid var(--line);padding:19px;border-radius:8px}.stat b{display:block;font-size:27px;font-weight:550;margin-bottom:6px}.stat span{font-size:11px;color:var(--muted)}.note{padding:13px 17px;border-left:3px solid #8b9f76;background:#e8eee1;color:#52634d;font-size:12px;line-height:1.7;margin-bottom:20px}.filters{display:flex;gap:8px;margin:17px 0;flex-wrap:wrap}input,select,textarea{border:1px solid #ccd7c8;border-radius:6px;padding:10px 12px;background:white;color:var(--ink)}.filters input{flex:1;min-width:190px}.count{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;margin:17px 0}.tablewrap{border:1px solid var(--line);border-radius:8px;background:white;overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th{font-size:10px;letter-spacing:.8px;color:var(--muted);background:#edf1e9;padding:13px;white-space:nowrap}td{padding:17px 13px;border-top:1px solid var(--line);font-size:12px;vertical-align:top}td strong{display:block;font-size:13px;margin-bottom:6px}.muted{font-size:11px;color:var(--muted);line-height:1.7}.tag{display:inline-block;font-size:10px;border-radius:4px;padding:4px 7px;background:#edf1e8;color:#62725c;margin:0 3px 4px 0;white-space:nowrap}.good{background:#e1eddf;color:#31603b}.bad{background:#f8e5dd;color:#a04d32}.warn{background:#f5edd7;color:#846b2c}.url{display:block;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:4px 0;font-size:11px}.reviewbutton{font-size:11px;white-space:nowrap}.empty{text-align:center;padding:50px;color:var(--muted)}dialog{width:min(710px,calc(100% - 30px));border:1px solid #cbd8c5;border-radius:12px;padding:28px;background:var(--bg);color:var(--ink)}dialog::backdrop{background:#0a1f1680;backdrop-filter:blur(3px)}dialog h2{font-size:23px;letter-spacing:-.7px;margin:0 0 6px}.evidence{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.box{padding:16px;background:white;border:1px solid var(--line);border-radius:7px}.box h3{font-size:12px;margin:0 0 12px}.box ul{padding-left:16px;font-size:12px;line-height:1.8}.related{margin:15px 0;max-height:170px;overflow:auto}.relative{padding:10px;background:white;border-bottom:1px solid var(--line);font-size:12px}.formrow{display:flex;gap:12px;margin-top:16px}.formrow label{display:flex;flex-direction:column;gap:7px;flex:1;font-size:12px}textarea{width:100%;min-height:75px}.modalactions{display:flex;justify-content:space-between;margin-top:20px}.toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:#243f2d;color:white;border-radius:7px;padding:12px 20px;z-index:10;font-size:12px}.hidden{display:none}.smallbtn{font-size:11px;padding:6px 9px}.progress{font-size:12px;color:#58754a;min-height:20px}.decision-keep{background:#dcebdd!important;color:#234e2c!important}.decision-review{background:#faedc9!important;color:#654608!important}.decision-archive{background:#f6deda!important;color:#792e26!important}.decision-undecided{background:#eceeea!important;color:#48534a!important}.inventory-notes{margin-top:6px;max-width:32ch;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.45}.inventory-notes-label{display:block;font-weight:600;color:var(--muted);margin-bottom:2px}.mobiletitle{display:none}@media(max-width:1050px){.shell{grid-template-columns:180px 1fr}aside{padding:25px 12px}main{padding:25px 20px}.stats{grid-template-columns:repeat(3,1fr)}.top{align-items:start;flex-direction:column}}@media(max-width:650px){.shell{display:block}aside{height:auto;position:relative;padding:17px}.brand{font-size:17px}.adminlabel{margin:9px 0}.sidefoot{display:none}aside nav{display:flex;overflow:auto}aside nav button{width:auto;white-space:nowrap;padding:8px}aside a{display:inline-block;padding:8px}.stats{grid-template-columns:repeat(2,1fr);gap:8px}.stat{padding:14px}main{padding:22px 14px}.evidence{grid-template-columns:1fr}.formrow{flex-direction:column}.filters select{flex:1;min-width:140px}}\n.row-actions{display:flex;flex-direction:column;align-items:flex-start;gap:8px}.dashboard-remove{color:#84231e}.dashboard-remove:hover{background:#fff5f3}.danger{background:#9f302a;border-color:#9f302a;color:white}.danger:hover{background:#84231e}.danger:disabled{opacity:.55}#github-delete-dialog{max-width:540px}#github-delete-message{color:#9f302a}</style></head><body><div class=\"shell\"><aside><div class=\"brand\">palawan<br>collective.</div><div class=\"adminlabel\">Private workspace</div><nav><button data-view=\"all\" class=\"active\">All code & websites</button><button data-view=\"review\">Review queue</button><button data-view=\"decided\">Your decisions</button></nav><a href=\"/#library\">Portfolio manager \u2197</a><a href=\"/\">Preview portfolio \u2197</a><div class=\"sidefoot\">Inventory stays in admin.<br>Decisions label records.<br>GitHub deletion requires confirmation.</div></aside><main><div class=\"top\"><div><div class=\"eyebrow\">Three GitHub accounts \u00b7 two Vercel accounts</div><h1>Code inventory</h1></div><div class=\"actions\"><button id=\"import\">Update inventory</button><button id=\"export\">Export decisions</button><button class=\"primary\" id=\"checkall\">Check website URLs</button></div></div><p class=\"subtitle\">Find the right repo, open its website, and decide what deserves to stay.</p><div id=\"stats\" class=\"stats\"></div><div class=\"note\" id=\"statusnote\">Loading your inventory\u2026</div><div id=\"progress\" class=\"progress\" role=\"status\"></div><div class=\"filters\"><input id=\"search\" placeholder=\"Search a business, repo or website\u2026\" aria-label=\"Search inventory\"><select id=\"owner\" aria-label=\"GitHub account\"><option value=\"\">All GitHub accounts</option></select><select id=\"team\" aria-label=\"Vercel account\"><option value=\"\">All Vercel accounts</option></select><select id=\"family\" aria-label=\"Project family\"><option value=\"\">All project families</option></select><select id=\"status\" aria-label=\"Review filter\"><option value=\"\">All recommendations</option><option>Keep candidate</option><option>Compare versions</option><option>Fix deployment</option><option>Archive candidate</option><option>Needs inspection</option><option value=\"deployed\">Has Vercel deployment</option><option value=\"responding\">Website responds</option><option value=\"no-url\">No deployment found</option></select></div><div class=\"count\"><span id=\"count\"></span><span id=\"scandate\"></span></div><div id=\"table\" class=\"tablewrap\"></div><input type=\"file\" id=\"inventoryfile\" accept=\"application/json,.json\" class=\"hidden\"></main></div><dialog id=\"github-delete-dialog\" aria-labelledby=\"github-delete-title\"><form id=\"github-delete-form\"><h2 id=\"github-delete-title\">Delete GitHub repo</h2><p id=\"github-delete-target\"></p><p id=\"github-delete-deployments\" class=\"muted\"></p><p class=\"muted\">GitHub will delete this repository and its associated history. Create a fine-grained token scoped to this repo with <strong>Administration: Read and write</strong>. The dashboard uses the token for this request and does not save it. <a href=\"https://github.com/settings/personal-access-tokens/new\" target=\"_blank\" rel=\"noopener noreferrer\">Create token on GitHub \u2197</a></p><div class=\"formrow\"><label>GitHub token<input id=\"github-delete-token\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\" required></label></div><div class=\"formrow\"><label>Type the exact owner/repository name<input id=\"github-delete-confirmation\" autocomplete=\"off\" spellcheck=\"false\" required></label></div><p id=\"github-delete-message\" role=\"status\"></p><div class=\"modalactions\"><button type=\"button\" id=\"github-delete-cancel\">Cancel</button><button type=\"submit\" class=\"danger\" id=\"github-delete-submit\">Delete from GitHub</button></div></form></dialog><dialog id=\"detail\"><div id=\"details\"></div></dialog><div id=\"toast\" class=\"toast hidden\" role=\"status\"></div><script>\nconst $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const link=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?esc(u.href):''}catch{return ''}};let inventory,rows=[],currentView='all',decisions={},health={},selected=null,checking=false;function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),4000)}async function api(path,options={}){const r=await fetch(path,{cache:'no-store',...options});const b=await r.json();if(!r.ok)throw Error(b.error||'Request failed');return b}function family(name){const s=name.toLowerCase();for(const [pattern,label] of [[/jaycee/,'JayCee'],[/azarraga/,'Azarraga'],[/baia|baiasanvic/,'BAIA'],[/sanvic|san-vicente/,'San Vicente'],[/kapwa|hop-hospitality/,'Hospitality OS'],[/sbi/,'SBI'],[/pinoy|link-in-bio/,'Link in bio'],[/prompt.?forge/,'PromptForge'],[/merqato|collective|digital-agency/,'Agency'],[/golden-goose/,'Golden Goose'],[/amuma/,'Amuma'],[/tala/,'Tala'],[/nfc/,'QR & NFC'],[/agent|hermes/,'Agents'],[/resort|glamp/,'Resort sites']])if(pattern.test(s))return label;return 'Other projects'}\nconst pushDateFormat = new Intl.DateTimeFormat('en-PH', {\n  year: 'numeric', month: 'short', day: 'numeric', timeZone: 'Asia/Manila'\n});\nfunction lastCodePush(date) {\n  return date ? pushDateFormat.format(new Date(date)) : 'Unknown';\n}\nfunction loadRows(){const map=new Map();for(const repo of inventory.repositories){const key=repo.name.toLowerCase(),audit=(inventory.repoAudits||[]).find(a=>a.repo.toLowerCase()===key);map.set(key,{id:key,name:repo.name.split('/').slice(1).join('/'),owner:repo.owner||repo.name.split('/')[0],repo:repo.name,repoURL:repo.url,repositoryId:String(repo.id),pushedAt:repo.pushedAt,audit,deployments:[],visibility:repo.visibility})}for(const p of inventory.projects){const key=p.repo?p.repo.toLowerCase():'unlinked:'+p.projectId;let row=map.get(key);if(!row){row={id:key,name:p.repo?p.repo.split('/')[1]:p.project,owner:p.repo?p.repo.split('/')[0]:'Unknown source',repo:p.repo,repoURL:p.repoURL,audit:null,deployments:[],visibility:'Not in repo inventory'};map.set(key,row)}row.deployments.push(p)}rows=[...map.values()].filter(row=>!removedRows.has(row.id));rows.forEach(r=>{r.family=decisions[r.id]?.family||family(r.name);r.score=(r.audit?.hasSource?2:0)+(r.audit?.hasReadme?1:0)+(r.audit?.hasTests?2:0)+(r.audit?.hasCI?2:0)+(r.audit?.hasLockfile?1:0)+(r.audit?.hasEnvExample?1:0)+(r.deployments.some(d=>d.state==='READY')?3:0)});rows.sort((a,b)=>a.family.localeCompare(b.family)||b.score-a.score||a.name.localeCompare(b.name));}\nfunction recommendation(r){const copy=(inventory.verifiedCopies||[]).find(g=>g.pair.some(n=>n.toLowerCase()===r.id));if(copy){const peer=rows.find(x=>copy.pair.some(n=>n.toLowerCase()===x.id)&&x.id!==r.id);if(peer){const linked=r.deployments.some(d=>d.state==='READY'),peerLinked=peer.deployments.some(d=>d.state==='READY');if(linked&&!peerLinked)return {label:'Keep candidate',reason:'The other repo has identical default-branch files. This copy is linked to a successful Vercel build.',cls:'good'};if(peerLinked&&!linked)return {label:'Archive candidate',reason:'Default-branch files match '+peer.repo+'. Keep the deployed copy; confirm other branches, issues and integrations before archiving.',cls:'warn'};return {label:'Compare versions',reason:'Default-branch files match '+peer.repo+'. Confirm which account should own the project before archiving a copy.',cls:'warn'}}}if(r.audit?.accessible&&r.audit.sizeKB===0&&r.audit.files===0)return {label:'Archive candidate',reason:'Repository is empty. Check whether it was reserved for planned work.',cls:'warn'};if(r.deployments.some(d=>d.state==='ERROR'))return {label:'Fix deployment',reason:'Latest deployment reports a build error. This is not evidence that the code should be discarded.',cls:'bad'};if(r.deployments.length>1||rows.filter(x=>x.family===r.family&&r.family!=='Other projects').length>1)return {label:'Compare versions',reason:'Related versions or multiple deployments exist. Compare the evidence before choosing a keeper.',cls:'warn'};if(r.audit?.hasSource&&r.deployments.some(d=>d.state==='READY'))return {label:'Keep candidate',reason:'Source files found and a linked deployment built successfully. Runtime behavior still needs checking.',cls:'good'};return {label:'Needs inspection',reason:r.audit?.hasSource?'Source exists, but no matching Vercel deployment was found in these two accounts. It may be hosted elsewhere.':'Source files have not been inspected or the source link is missing.',cls:''}}\nfunction filters(){return rows.filter(r=>{const rec=recommendation(r),q=$('#search').value.toLowerCase();if(currentView==='decided'&&!decisions[r.id]?.decision)return false;if(currentView==='review'&&rec.label==='Keep candidate')return false;if($('#owner').value&&r.owner!==$('#owner').value)return false;if($('#family').value&&r.family!==$('#family').value)return false;if($('#team').value&&!r.deployments.some(d=>d.vercelTeam===$('#team').value))return false;const status=$('#status').value;if(status==='deployed'&&!r.deployments.length)return false;if(status==='no-url'&&r.deployments.length)return false;if(status==='responding'&&!r.deployments.some(d=>health[d.projectId]?.status==='responding')&&health['repo:'+r.id]?.status!=='responding')return false;if(status&&!['deployed','no-url','responding'].includes(status)&&rec.label!==status)return false;return [r.name,r.repo,r.owner,r.family,...r.deployments.flatMap(d=>[d.project,d.vercelTeam,...d.domains])].join(' ').toLowerCase().includes(q)})}\nfunction homepage(r){const u=r.audit?.homepage;try{return new URL(u).hostname!=='github.com'?u:''}catch{return ''}}function homepageConflict(r){const url=homepage(r);if(!url)return null;let host;try{host=new URL(url).hostname.toLowerCase()}catch{return null}return inventory.projects.find(p=>p.repo&&p.repo.toLowerCase()!==r.repo?.toLowerCase()&&(p.domains||[]).some(d=>d.toLowerCase()===host))}function homepageHTML(r){const url=homepage(r);if(!url)return '';const conflict=homepageConflict(r),key='repo:'+r.id;return '<div style=\"margin-top:8px\"><span class=\"tag\">URL listed by GitHub</span>'+healthLabel({projectId:key})+'<a class=\"url\" href=\"'+link(url)+'\" target=\"_blank\" rel=\"noopener\">'+esc(url.replace(/^https?:\\/\\//,''))+' \u2197</a>'+(conflict?'<div class=\"muted\" style=\"color:#a05d35\">Vercel source: '+esc(conflict.repo)+'</div>':'<div class=\"muted\">Source link not verified by Vercel</div>')+'</div>'}function healthLabel(d){const h=health[d.projectId];if(!h)return '<span class=\"tag\">Website not checked</span>';return '<span class=\"tag '+(h.status==='responding'?'good':h.status==='protected'?'warn':'bad')+'\">'+esc(h.label)+'</span>'}\nconst decisionStyles = {\n  'Keep': 'decision-keep',\n  'Review': 'decision-review',\n  'Archive candidate': 'decision-archive',\n  'Not decided': 'decision-undecided'\n};\nfunction decisionCell(id, recommendation) {\n  const saved=decisions[id], label=saved?.decision||'Not decided';\n  const note=saved?.notes;\n  return '<span class=\"tag '+(decisionStyles[label]||decisionStyles['Not decided'])+'\">'+esc(label)+'</span>'\n    +(!saved?.decision?'<div class=\"muted\">'+esc(recommendation.label)+'</div>':'')\n    +(note?.trim()?'<div class=\"inventory-notes\"><span class=\"inventory-notes-label\">Notes</span>'+esc(note)+'</div>':'');\n}\nfunction render(){const filtered=filters(),visibleProjects=rows.flatMap(r=>r.deployments);$('#count').textContent=filtered.length+' records \u00b7 '+rows.length+' total';$('#stats').innerHTML=[[rows.filter(r=>r.repositoryId).length,'Repos inventoried'],[visibleProjects.length,'Vercel projects'],[rows.filter(r=>r.audit?.sizeKB===0).length,'Empty repositories'],[visibleProjects.filter(p=>p.state==='ERROR').length,'Latest build errors'],[visibleProjects.filter(p=>health[p.projectId]?.status==='responding').length,'Vercel URLs responding']].map(([n,t])=>'<div class=\"stat\"><b>'+n+'</b><span>'+t+'</span></div>').join('');$('#table').innerHTML='<table><thead><tr><th>Repository / account</th><th>Vercel & website</th><th>Code evidence</th><th>Decision &amp; notes</th><th></th></tr></thead><tbody>'+filtered.map(r=>{const rec=recommendation(r),a=r.audit;return '<tr><td><strong>'+esc(r.name)+'</strong>'+(githubDeletionReceipts.has(r.repositoryId)?'<span class=\"tag warn\">'+(githubDeletionReceipts.get(r.repositoryId).status==='deleted'?'Deleted on GitHub':'Deletion submitted')+'</span>':'')+'<div class=\"muted\">'+esc(r.owner)+' \u00b7 '+esc(r.family)+'</div>'+(r.repositoryId?'<div class=\"muted\">Last code push: '+esc(lastCodePush(r.pushedAt))+'</div>':'')+(link(r.repoURL)?'<a class=\"url\" href=\"'+link(r.repoURL)+'\" target=\"_blank\" rel=\"noopener\">Open GitHub \u2197</a>':'<span class=\"tag warn\">Source unknown</span>')+'</td><td>'+(r.deployments.length?r.deployments.map(d=>{const url=d.domains?.[0]?'https://'+d.domains[0]:d.deploymentURL;return '<div><span class=\"tag '+(d.state==='READY'?'good':d.state==='ERROR'?'bad':'')+'\">'+(d.state==='READY'?'Build OK':esc(d.state||'Unknown build'))+'</span>'+healthLabel(d)+'<div class=\"muted\">'+esc(d.vercelTeam)+'</div><a class=\"url\" href=\"'+link(url)+'\" target=\"_blank\" rel=\"noopener\">'+esc(d.domains?.[0]||d.project)+' \u2197</a></div>'}).join('<hr style=\"border:0;border-top:1px solid #edf0e9\">'):'<span class=\"muted\">No linked deployment found</span>')+homepageHTML(r)+'</td><td>'+(a?.treeRead?'<div class=\"muted\">'+a.files+' files \u00b7 '+esc(a.language||'Mixed')+'</div>'+[['hasTests','Test files'],['hasCI','CI workflow'],['hasReadme','README'],['hasLockfile','Lockfile']].filter(([k])=>a[k]).map(([k,t])=>'<span class=\"tag\">'+t+'</span>').join(''):'<span class=\"muted\">Not inspected</span>')+'</td><td>'+decisionCell(r.id,rec)+'</td><td><div class=\"row-actions\"><button class=\"reviewbutton\" data-review=\"'+esc(r.id)+'\">Review \u2192</button>'+(inventory.canRemoveRows?'<button type=\"button\" class=\"smallbtn dashboard-remove\" data-dashboard-remove=\"'+esc(r.id)+'\">Delete from dashboard</button>':'')+'</div></td></tr>'}).join('')+'</tbody></table>'+(!filtered.length?'<div class=\"empty\">No records match these filters.</div>':'');document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openDetail(b.dataset.review));document.querySelectorAll('[data-dashboard-remove]').forEach(b=>b.onclick=()=>removeDashboardRow(b))}\nlet removedRows = new Set();\nconst pendingRemovals = new Set();\n\nasync function removeDashboardRow(button) {\n  const id = button.dataset.dashboardRemove;\n  const row = rows.find(r => r.id === id);\n  if (!row || pendingRemovals.has(id) ||\n      !window.confirm('Delete ' + (row.repo || row.name) + ' from the dashboard? This only removes the dashboard entry.')) return;\n\n  pendingRemovals.add(id);\n  button.disabled = true;\n  try {\n    await api('/api/inventory/dashboard-removal', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({id})\n    });\n    removedRows.add(id);\n    loadRows();\n    render();\n    toast('Deleted from dashboard: ' + (row.repo || row.name));\n  } catch (error) {\n    toast(error.message);\n  } finally {\n    pendingRemovals.delete(id);\n    button.disabled = false;\n  }\n}\nlet githubDeletionEnabled = false;\nconst githubDeletionReceipts = new Map();\n\nasync function loadGitHubDeletionState() {\n  try {\n    const result = await api('/api/inventory/github-deletion');\n    githubDeletionEnabled = result.enabled;\n    for (const receipt of result.receipts) githubDeletionReceipts.set(receipt.repositoryId, receipt);\n  } catch {\n    githubDeletionEnabled = false;\n  }\n}\n\nfunction openGitHubDelete(row) {\n  const dialog = $('#github-delete-dialog');\n  const form = $('#github-delete-form');\n  const input = $('#github-delete-token');\n  const confirmation = $('#github-delete-confirmation');\n  const message = $('#github-delete-message');\n  const submit = $('#github-delete-submit');\n  const cancel = $('#github-delete-cancel');\n  form.reset();\n  message.textContent = '';\n  submit.disabled = false;\n  $('#github-delete-target').textContent = row.repo;\n  const projects = row.deployments.map(deployment => deployment.project);\n  $('#github-delete-deployments').textContent = projects.length\n    ? 'Linked Vercel projects: ' + projects.join(', ') + '. Their Git integration may be affected.'\n    : 'No linked Vercel project in this inventory.';\n  cancel.onclick = () => dialog.close();\n  dialog.oncancel = event => { if (submit.disabled) event.preventDefault(); };\n  dialog.onclose = () => form.reset();\n  form.onsubmit = async event => {\n    event.preventDefault();\n    if (confirmation.value !== row.repo) {\n      message.textContent = 'Type ' + row.repo + ' exactly.';\n      return;\n    }\n    submit.disabled = true;\n    cancel.disabled = true;\n    message.textContent = 'Waiting for GitHub confirmation\u2026';\n    const payload = {\n      repositoryId: row.repositoryId,\n      confirmation: confirmation.value,\n      token: input.value.trim()\n    };\n    input.value = '';\n    try {\n      const receipt = await api('/api/inventory/github-deletion', {\n        method: 'POST',\n        headers: {'Content-Type': 'application/json'},\n        body: JSON.stringify(payload)\n      });\n      githubDeletionReceipts.set(row.repositoryId, receipt);\n      dialog.close();\n      openDetail(row.id);\n      render();\n      toast(receipt.receiptSaved === false\n        ? 'GitHub confirmed deletion. The dashboard could not save the receipt.'\n        : 'Deleted from GitHub: ' + row.repo);\n    } catch (error) {\n      await loadGitHubDeletionState();\n      message.textContent = error.message;\n      if (githubDeletionReceipts.has(row.repositoryId)) {\n        dialog.close();\n        openDetail(row.id);\n        render();\n        toast(error.message);\n      }\n    } finally {\n      payload.token = '';\n      submit.disabled = false;\n      cancel.disabled = false;\n    }\n  };\n  dialog.showModal();\n}\n\nfunction openDetail(id){selected=rows.find(x=>x.id===id);const r=selected,a=r.audit,rec=recommendation(r),saved=decisions[id]||{},related=rows.filter(x=>x.family===r.family&&x.id!==id&&r.family!=='Other projects');$('#details').innerHTML='<div class=\"eyebrow\">'+esc(r.family)+' / '+esc(r.owner)+'</div><h2>'+esc(r.name)+'</h2><p class=\"muted\">'+esc(a?.description||r.repo||'Deployment without an identified source repo')+'</p><div class=\"note\"><strong>'+rec.label+'</strong><br>'+esc(rec.reason)+'</div>'+((inventory.reviewNotes||[]).find(n=>n.repo.toLowerCase()===r.id)?.note?'<p class=\"muted\">'+esc((inventory.reviewNotes||[]).find(n=>n.repo.toLowerCase()===r.id).note)+'</p>':'')+'<div class=\"evidence\"><div class=\"box\"><h3>Source evidence</h3><ul><li>Source files: '+(a?.hasSource?'Found':'Not confirmed')+'</li><li>README: '+(a?.hasReadme?'Found':'Not found')+'</li><li>Test files: '+(a?.hasTests?'Found \u2014 not executed':'Not found')+'</li><li>CI workflow: '+(a?.hasCI?'Found \u2014 results not reviewed':'Not found')+'</li><li>Last code push: '+esc(lastCodePush(r.pushedAt))+'</li><li>Repo size: '+(a?.sizeKB??'Unknown')+' KB</li></ul><p class=\"muted\">Structure inspection only. These signals do not prove code quality or that features work.</p></div><div class=\"box\"><h3>Deployment evidence</h3>'+r.deployments.map(d=>'<p class=\"muted\"><b>'+esc(d.project)+'</b><br>'+esc(d.vercelTeam)+' \u00b7 '+esc(d.state||'Unknown')+'<br>Branch: '+esc(d.branch||'Unknown')+'</p>'+healthLabel(d)+'<div><button class=\"smallbtn\" data-check=\"'+esc(d.projectId)+'\">Check URL</button> <a target=\"_blank\" rel=\"noopener\" href=\"'+link(d.domains?.[0]?'https://'+d.domains[0]:d.deploymentURL)+'\">Open website \u2197</a><span class=\"muted\" data-checkresult></span></div>').join('')+(!r.deployments.length?'<p class=\"muted\">No matching Vercel deployment in the scanned accounts. This does not mean the code is unused.</p>':'')+homepageHTML(r)+(homepage(r)?'<button class=\"smallbtn\" data-check=\"repo:'+esc(r.id)+'\">Check GitHub-listed URL</button>':'')+'</div></div>'+(related.length?'<h3 style=\"font-size:13px\">Related versions \u00b7 grouping needs review</h3><p class=\"muted\">Listed by evidence score, not a full code-quality verdict. Keep different versions if they serve different purposes.</p><div class=\"related\">'+related.map(x=>'<div class=\"relative\"><b>'+esc(x.repo||x.name)+'</b><br><span class=\"muted\">'+x.score+'/12 evidence signals \u00b7 '+(x.deployments.length?x.deployments.map(d=>d.state||'Unknown').join(', '):'No matched deployment')+'</span> <button class=\"smallbtn\" data-related=\"'+esc(x.id)+'\">Compare</button></div>').join('')+'</div>':'')+'<form id=\"decisionform\"><div class=\"formrow\"><label>Your decision<select id=\"decision\"><option value=\"\" class=\"decision-undecided\">Not decided</option>'+['Keep','Review','Archive candidate'].map(x=>'<option class=\"'+decisionStyles[x]+'\" '+(saved.decision===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>Project family<input id=\"groupname\" value=\"'+esc(r.family)+'\" maxlength=\"100\"></label></div><label style=\"display:block;font-size:12px;margin:16px 0 7px\">Notes / why this version</label><textarea id=\"notes\" maxlength=\"3000\" placeholder=\"What works? What is missing? Why keep this one?\">'+esc(saved.notes||'')+'</textarea><div class=\"modalactions\"><button type=\"button\" id=\"close\">Close</button><button class=\"primary\" id=\"save\">Save decision</button></div></form>';const receipt = githubDeletionReceipts.get(r.repositoryId);\nif (receipt) {\n  const status = document.createElement('p');\n  status.className = 'muted';\n  status.textContent = receipt.status === 'deleted' ? 'Deleted on GitHub' : 'Deletion submitted. Verify the result in GitHub.';\n  $('#details').append(status);\n} else if (githubDeletionEnabled && r.repositoryId) {\n  const button = document.createElement('button');\n  button.type = 'button';\n  button.className = 'danger';\n  button.textContent = 'Delete GitHub repo';\n  button.onclick = () => openGitHubDelete(r);\n  $('#details').append(button);\n}\nconst decisionSelect=$('#decision');\nconst updateDecisionColor=()=>{decisionSelect.className=decisionStyles[decisionSelect.value||'Not decided'];};\ndecisionSelect.onchange=updateDecisionColor;\nupdateDecisionColor();\n$('#close').onclick=()=>$('#detail').close();$('#decisionform').onsubmit=async e=>{e.preventDefault();$('#save').disabled=true;try{const body={id:r.id,decision:$('#decision').value,notes:$('#notes').value,family:$('#groupname').value};await api('/api/inventory/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});decisions[r.id]=body;loadRows();fillSelect('family',[...new Set(rows.map(x=>x.family))]);render();$('#detail').close();toast('Decision saved. No repository was changed.')}catch(err){toast(err.message);$('#save').disabled=false}};document.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>openDetail(b.dataset.related));document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{b.disabled=true;await checkURL(b.dataset.check);b.disabled=false;b.textContent='Check again';const result=b.parentNode.querySelector('[data-checkresult]');if(result)result.textContent=' '+(health[b.dataset.check]?.label||'Could not verify')});if(!$('#detail').open)$('#detail').showModal()}\nfunction fillSelect(id,values){const e=$('#'+id),old=e.value,label=e.options[0].textContent;e.innerHTML='<option value=\"\">'+label+'</option>'+values.sort().map(x=>'<option>'+esc(x)+'</option>').join('');e.value=old}\nasync function checkURL(id){try{const x=await api('/api/inventory/check',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:id})});health[id]=x;render()}catch(e){toast(e.message)}}\nasync function init(){try{[inventory]=await Promise.all([api('/api/inventory'),loadGitHubDeletionState()]);decisions=inventory.decisions||{};health=inventory.health||{};removedRows=new Set(inventory.removedRows);loadRows();fillSelect('owner',[...new Set(rows.map(x=>x.owner))]);fillSelect('team',[...new Set(inventory.projects.map(x=>x.vercelTeam))]);fillSelect('family',[...new Set(rows.map(x=>x.family))]);$('#scandate').textContent='Account snapshot: '+inventory.capturedOn;$('#statusnote').textContent='Recommendations are a first pass, not deletion instructions. Related versions are grouped by name; confirm their purpose. Build OK means Vercel compiled it. Website responds means an HTTP check succeeded\u2014not that booking, payments or other features passed testing. Account sync is a saved snapshot; URL checks run live.';render()}catch(e){$('#table').innerHTML='<div class=\"empty\">'+esc(e.message)+' <button onclick=\"location.reload()\">Retry</button></div>'}}\n['search','owner','team','family','status'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#checkall').onclick=async()=>{if(checking)return;checking=true;$('#checkall').disabled=true;const targets=[...rows.flatMap(r=>r.deployments.map(p=>p.projectId)),...rows.filter(r=>homepage(r)).map(r=>'repo:'+r.id)];let done=0;for(let i=0;i<targets.length;i+=5){await Promise.allSettled(targets.slice(i,i+5).map(id=>checkURL(id)));done=Math.min(i+5,targets.length);$('#progress').textContent='Checked '+done+' of '+targets.length+' website URLs.'}checking=false;$('#checkall').disabled=false;toast('URL checks saved. Open Review to see the results.')};$('#export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({capturedOn:inventory.capturedOn,decisions,health},null,2)],{type:'application/json'}));a.href=url;a.download='code-inventory-decisions.json';a.click();URL.revokeObjectURL(url)};$('#import').onclick=()=>$('#inventoryfile').click();$('#inventoryfile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.repositories)||!Array.isArray(data.projects))throw Error('Use an account inventory JSON export.');await api('/api/inventory',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});await init();toast('Inventory updated. Your decisions are preserved.')}catch(err){toast(err.message)}};init();\n</script></body></html>\n";
